package com.booksyde.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="marketplace_listings",schema="public")
public class MarketplaceListingEntity { @Id private UUID id; @Column(name="seller_id",nullable=false) private UUID sellerId; @Column(name="manga_id") private UUID mangaId; @Column(nullable=false) private String title; @Column(nullable=false) private String author; @Column(nullable=false) private String category; @Column(name="cover_url") private String coverUrl; @Column(name="price_cents",nullable=false) private int priceCents; @Column(nullable=false) private String currency; @Column(nullable=false) private boolean active; @Column(name="target_type",nullable=false) private String targetType; @Column(name="work_type",nullable=false) private String workType; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; protected MarketplaceListingEntity(){} public UUID getId(){return id;} public UUID getSellerId(){return sellerId;} public UUID getMangaId(){return mangaId;} public String getTitle(){return title;} public String getAuthor(){return author;} public String getCategory(){return category;} public String getCoverUrl(){return coverUrl;} public int getPriceCents(){return priceCents;} public String getCurrency(){return currency;} public boolean isActive(){return active;} public String getTargetType(){return targetType;} public String getWorkType(){return workType;} }
